// Stand for 4 standard 1 cm spectrophotometer cuvettes
// Print orientation: base on z = 0, pockets open upward (+Z)

// ---------- Block ----------
block_x = 88;     // block length along X (mm)
block_y = 28;     // block width along Y (mm)
block_h = 28;     // block height along Z (mm)

// ---------- Pockets ----------
n_pockets     = 4;     // number of cuvette pockets
pocket_w      = 13.2;  // pocket size in X and Y (mm)
pocket_depth  = 24;    // pocket depth from top face (mm)
pocket_pitch  = 20.2;  // centre-to-centre spacing along X (mm)
floor_t       = block_h - pocket_depth; // remaining floor thickness = 4 mm

// ---------- Misc ----------
eps = 0.5;   // overshoot so cutters pass cleanly through the top face
$fn = 64;    // circle resolution (no curves here, set per the rules)

// X position of the first pocket so the row is centred on the block
first_x = -(n_pockets - 1) * pocket_pitch / 2;

difference() {
    // Main block, centred in X/Y, standing on z = 0
    translate([-block_x / 2, -block_y / 2, 0])
        cube([block_x, block_y, block_h]);

    // Row of square pockets opened from the top face
    for (i = [0 : n_pockets - 1])
        translate([first_x + i * pocket_pitch - pocket_w / 2,
                   -pocket_w / 2,
                   floor_t])
            cube([pocket_w, pocket_w, pocket_depth + eps]);
}
