```openscad
// Horizontal pipette rest
// Units: mm

$fn = 96;

// Base plate
base_len   = 120;   // plate length (X)
base_wid   = 40;    // plate width (Y)
base_thk   = 5;     // plate thickness (Z)

// Uprights
up_thk     = 8;     // upright thickness in X
up_hgt     = 30;    // upright height from bed (Z)

// Cradle notch
notch_r    = 7;     // semicircular notch radius
notch_z    = up_hgt; // notch centre height (on top edge)

eps        = 0.5;   // overcut for clean differences

difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights, flush with each end
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - up_thk : -base_len/2, -base_wid/2, 0])
                cube([up_thk, base_wid, up_hgt]);
    }

    // Cradle notches through each upright along X
    for (sx = [-1, 1])
        translate([sx * (base_len/2 - up_thk/2), 0, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps, center = true);
}
