// Horizontal pipette rest
// Base plate with two end uprights, each with a semicircular cradle notch

$fn = 96;

// --- Base plate ---
base_len    = 180;   // plate length along X
base_wid    = 40;    // plate width along Y
base_thk    = 6;     // plate thickness (z = 0 to 6)

// --- Uprights ---
up_thk      = 8;     // upright thickness along X
up_wid      = base_wid; // upright width along Y (same as plate)
up_hgt      = 40;    // upright height (z = 0 to 40)

// --- Cradle notch ---
notch_r     = 10;    // semicircular notch radius
notch_y     = 0;     // notch centre Y
notch_z     = up_hgt; // notch centre Z (on top edge)

eps         = 0.5;   // overcut for clean differences

difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights, flush with each end of the plate
        for (sx = [-1, 1])
            translate([sx > 0 ? base_len/2 - up_thk : -base_len/2, -up_wid/2, 0])
                cube([up_thk, up_wid, up_hgt]);
    }

    // Cradle notches through each upright along X
    for (sx = [-1, 1]) {
        x0 = sx > 0 ? base_len/2 - up_thk : -base_len/2;
        translate([x0 - eps, notch_y, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
    }
}
