```openscad
// Horizontal pipette rest
// Units: mm

$fn = 96;

// Base plate
base_len   = 120;  // plate length (X)
base_wid   = 30;   // plate width (Y)
base_thk   = 4;    // plate thickness (Z)

// Uprights
up_thk     = 8;    // upright thickness in X
up_h       = 30;   // upright height (top at z = 30)

// Cradle notch
notch_r    = 8;    // semicircular notch radius, centre at y=0, z=up_h

// Overcut
eps        = 0.5;  // extension of cutters past faces

union() {
    // Base plate
    translate([-base_len/2, -base_wid/2, 0])
        cube([base_len, base_wid, base_thk]);

    // Uprights at each end, flush with plate ends
    for (s = [-1, 1]) {
        x0 = (s < 0) ? -base_len/2 : base_len/2 - up_thk;
        difference() {
            translate([x0, -base_wid/2, 0])
                cube([up_thk, base_wid, up_h]);
            // Cradle notch running along X
            translate([x0 - eps, 0, up_h])
                rotate([0, 90, 0])
                    cylinder(r = notch_r, h = up_thk + 2*eps);
        }
    }
}
