```openscad
// Horizontal pipette rest
// Print orientation: base plate on the bed (z = 0), uprights build upward (+Z)

$fn = 96;

// ---- Base plate ----
base_len   = 180;   // plate length along X (mm)
base_wid   = 30;    // plate width along Y (mm)
base_thk   = 5;     // plate thickness along Z (mm)

// ---- Uprights ----
up_thk     = 12;    // upright thickness along X (mm)
up_wid     = base_wid; // upright width along Y = plate width (mm)
up_hgt     = 40;    // upright height, from z = 0 (mm)

// ---- Cradle notch ----
notch_r    = 9;     // semicircular notch radius (mm)
notch_z    = up_hgt; // notch centre height = top edge (mm)
eps        = 0.5;   // cutter overshoot past faces (mm)

// X centre of each upright (flush with plate ends)
up_x = [ -base_len/2 + up_thk/2, base_len/2 - up_thk/2 ];

difference() {
    union() {
        // Base plate
        translate([-base_len/2, -base_wid/2, 0])
            cube([base_len, base_wid, base_thk]);

        // Uprights at each end
        for (x = up_x)
            translate([x - up_thk/2, -up_wid/2, 0])
                cube([up_thk, up_wid, up_hgt]);
    }

    // Semicircular cradle notches, axis along X through each upright
    for (x = up_x)
        translate([x - up_thk/2 - eps, 0, notch_z])
            rotate([0, 90, 0])
                cylinder(r = notch_r, h = up_thk + 2*eps);
}
