```openscad
// Flat hex-cap wrench for reagent bottles
// Print orientation: flat on bed, z = 0 to plate_t

// ---------------- Parameters ----------------
plate_t      = 8;     // plate thickness (Z)
head_d       = 55;    // round head diameter, centred on origin
handle_w     = 14;    // handle width (Y)
handle_x0    = 0;     // handle start (X)
handle_x1    = 110;   // handle end (X)
hex_af       = 32;    // hex hole size across flats
eps          = 0.5;   // cutter overshoot past faces

hex_r = hex_af / sqrt(3);  // hex circumradius from across-flats

$fn = 128;

// ---------------- Model ----------------
difference() {
    union() {
        // Round head
        cylinder(d = head_d, h = plate_t);
        // Straight handle
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }
    // Hexagonal hole: vertices on X axis -> two flats parallel to X
    translate([0, 0, -eps])
        cylinder(r = hex_r, h = plate_t + 2 * eps, $fn = 6);
}
```

```openscad
// Flat hex-cap wrench for reagent bottles
// Print orientation: flat on bed, z = 0 to plate_t

// ---------- Parameters ----------
plate_t      = 8;     // plate thickness (Z)
head_d       = 55;    // round head diameter, centred on origin
handle_w     = 18;    // handle width (Y), centred on y = 0
handle_x0    = 0;     // handle start (X)
handle_x1    = 120;   // handle end (X)
hex_af       = 24;    // hex hole size across flats
eps          = 0.5;   // cutter overshoot past faces

$fn = 128;

// Circumradius of hexagon from across-flats dimension
hex_r = (hex_af / 2) / cos(30);

// ---------- Model ----------
difference() {
    union() {
        // Round head
        cylinder(d = head_d, h = plate_t);

        // Straight handle
        translate([handle_x0, -handle_w / 2, 0])
            cube([handle_x1 - handle_x0, handle_w, plate_t]);
    }

    // Hexagonal hole: circle($fn=6) puts vertices on the X axis,
    // so two flats are parallel to the X axis
    translate([0, 0, -eps])
        linear_extrude(height = plate_t + 2 * eps)
            circle(r = hex_r, $fn = 6);
}
