```openscad
// Hex key organiser block
// Print orientation: base on z = 0, pockets open at the top

// ---- Block dimensions ----
block_l = 66;      // length along X
block_w = 16;      // width along Y
block_h = 25;      // height along Z

// ---- Pocket parameters ----
pocket_depth   = 12;                   // depth of each pocket from the top face
pocket_pitch   = 14;                   // centre-to-centre spacing along X
pocket_flats   = [4.4, 5.4, 6.4, 8.4]; // across-flats sizes, from -X to +X
pocket_count   = len(pocket_flats);    // number of pockets
cut_extra      = 0.5;                  // extra cut length past the top face

// Circumradius of a hexagon with the given across-flats size
function hex_r(af) = af / (2 * cos(30));

difference() {
    // Main block, centred in X and Y, standing on z = 0
    translate([-block_l/2, -block_w/2, 0])
        cube([block_l, block_w, block_h]);

    // Hexagonal pockets along y = 0
    for (i = [0 : pocket_count - 1]) {
        x = (i - (pocket_count - 1) / 2) * pocket_pitch;
        // cylinder with $fn = 6 puts vertices on the X axis,
        // so two flats are parallel to the X axis
        translate([x, 0, block_h - pocket_depth])
            cylinder(h = pocket_depth + cut_extra,
                     r = hex_r(pocket_flats[i]),
                     $fn = 6);
    }
}
