// Flat spacer ring - raises an instrument off the bench
// Units: mm. Print orientation: flat on bed, z = 0 upward.

// ---- Dimensions ----
ring_thickness   = 6;     // ring height (Z)
outer_diameter   = 100;   // ring outer diameter
inner_diameter   = 80;    // ring inner (bore) diameter
hole_diameter    = 5.5;   // through-hole diameter
hole_pcd         = 90;    // pitch circle diameter of holes
hole_count       = 3;     // number of evenly spaced holes
hole_start_angle = 0;     // first hole on +X axis (degrees)

// ---- Quality / tolerances ----
eps    = 0.5;             // cutter overshoot past faces
$fn    = 128;             // ring smoothness
hole_fn = 64;             // hole smoothness

// ---- Model ----
difference() {
    // Outer body
    cylinder(h = ring_thickness, d = outer_diameter);

    // Central bore
    translate([0, 0, -eps])
        cylinder(h = ring_thickness + 2 * eps, d = inner_diameter);

    // Through-holes on pitch circle
    for (i = [0 : hole_count - 1]) {
        a = hole_start_angle + i * 360 / hole_count;
        translate([hole_pcd / 2 * cos(a), hole_pcd / 2 * sin(a), -eps])
            cylinder(h = ring_thickness + 2 * eps, d = hole_diameter, $fn = hole_fn);
    }
}
