$fn = 96;         // curve resolution

// Rounded-end slot cutter, centred at origin, running along X
module slot_cutter() {
    translate([0, 0, -eps])
        hull() {
            for (sx = [-slot_cc / 2, slot_cc / 2])
                translate([sx, 0, 0])
                    cylinder(r = slot_r, h = plate_t + 2 * eps, $fn = 96);
        }
}

