// Adjustable shim plate with two rounded-end bolt slots
$fn = 64;

// Plate dimensions
plate_len   = 80;    // plate length along X
plate_wid   = 28;    // plate width along Y
plate_thk   = 3;     // plate thickness along Z

// Slot dimensions
