slot_len    = 12;    // slot overall length, end to end, along X
slot_xs     = [-20, 20]; // slot centre X positions
slot_y      = 0;     // slot centre Y position

// Cutting overshoot
eps         = 0.5;   // extension of cutters beyond faces

module slot(len, wid, h) {
    r = wid / 2;
    c = len / 2 - r;  // distance from slot centre to end-circle centres
    hull() {
        translate([-c, 0, 0]) cylinder(r = r, h = h, $fn = 64);
        translate([ c, 0, 0]) cylinder(r = r, h = h, $fn = 64);
    }
}

difference() {
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    for (x = slot_xs)
        translate([x, slot_y, -eps])
            slot(slot_len, slot_wid, plate_thk + 2 * eps);
}
