// Microplate riser
// Units: mm. Prints as modelled: legs on the bed (z = 0), top plate at the top.

// ---------- Dimensions ----------
plate_x      = 150;   // top plate length (X)
plate_y      = 95;    // top plate width (Y)
plate_t      = 5;     // top plate thickness
top_z        = 30;    // height of the top face of the plate
