```openscad
// Magnet carrier disc for rotating sample mixer
// Print orientation: flat on bed, magnet pockets facing up (+Z)
//
// NOTE: With 6 pockets of 10.2 mm diameter on a 19.8 mm pitch circle,
// adjacent pocket centres are only 9.9 mm apart (2 * 9.9 * sin(30deg)),
// so neighbouring pockets OVERLAP by about 0.3 mm. There is no wall
// between them at the top face. Magnets may snap toward each other.
// Increase pocket_circle_d to at least ~21 mm for a ~0.8 mm wall,
// or reduce the magnet size, if separate pockets are needed.

$fn = 96;

// ---- Disc body ----
disc_d          = 40;     // carrier disc outer diameter
disc_h          = 10;     // carrier disc height

// ---- Magnet pockets ----
pocket_count    = 6;      // number of magnet pockets
pocket_d        = 10.2;   // pocket diameter (disc magnet + clearance)
pocket_depth    = 2;      // pocket depth from top face
pocket_circle_d = 19.8;   // pitch circle diameter of pocket centres
pocket_start_a  = 0;      // angle of first pocket (0 = +X axis)

// ---- Shaft hole ----
shaft_d         = 5;      // motor shaft through-hole diameter

// ---- Modelling helper ----
eps             = 0.5;    // overshoot for clean boolean cuts

difference() {
    // Main disc, centred in XY, sitting on z = 0
    cylinder(d = disc_d, h = disc_h);

    // Magnet pockets cut into the top face
    for (i = [0 : pocket_count - 1]) {
        rotate([0, 0, pocket_start_a + i * 360 / pocket_count])
            translate([pocket_circle_d / 2, 0, disc_h - pocket_depth])
                cylinder(d = pocket_d, h = pocket_depth + eps);
    }

    // Central through-hole for motor shaft
    translate([0, 0, -eps])
        cylinder(d = shaft_d, h = disc_h + 2 * eps);
}
