    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    // Screw holes with countersinks
    for (i = [0 : hole_count - 1]) {
        translate([first_x + i * hole_pitch, 0, 0]) {
            // Through-hole
            translate([0, 0, -eps])
                cylinder(d = hole_d, h = bar_thick + 2 * eps);

            // 90-degree countersink, 9 mm at top face, extended above surface
            translate([0, 0, bar_thick - csk_depth])
                cylinder(d1 = hole_d, d2 = csk_top_d, h = csk_depth + eps);
        }
    }
}
