$fn = 64;

// ---- Bar dimensions ----
bar_length    = 84;   // X length (mm)
bar_width     = 16;   // Y width (mm)
bar_thick     = 6;    // Z thickness (mm)

// ---- Screw holes ----
hole_count    = 3;    // number of screw holes
hole_pitch    = 30;   // centre-to-centre spacing along X (mm)
hole_d        = 4.5;  // through-hole diameter (mm)
csk_d         = 9;    // countersink diameter at top surface (mm)
csk_angle     = 90;   // countersink included angle (degrees)

// ---- Derived / helper values ----
csk_depth     = (csk_d - hole_d) / 2 / tan(csk_angle / 2); // cone depth (mm)
eps           = 0.5;  // overshoot for clean cuts (mm)

// X positions of holes, centred on the bar
function hole_x(i) = (i - (hole_count - 1) / 2) * hole_pitch;

module countersunk_hole() {
    // Through-hole
    translate([0, 0, -eps])
        cylinder(h = bar_thick + 2 * eps, d = hole_d);
    // 90-degree countersink cone, extended above top face
    translate([0, 0, bar_thick - csk_depth])
        cylinder(h = csk_depth + eps,
                 d1 = hole_d,
                 d2 = csk_d + 2 * eps * tan(csk_angle / 2));
}

difference() {
    // Bar body, centred in X/Y, resting on z = 0
    translate([-bar_length / 2, -bar_width / 2, 0])
        cube([bar_length, bar_width, bar_thick]);

    // Countersunk screw holes along X at y = 0
    for (i = [0 : hole_count - 1])
        translate([hole_x(i), 0, 0])
            countersunk_hole();
}
