// Tubing reel - printed lying on the bottom flange
$fn = 96;

// Dimensions (mm)
flange_d   = 50;   // flange diameter
flange_t   = 3;    // flange thickness
core_d     = 30;   // core diameter
core_len   = 30;   // core length (z = 3 to z = 33)
bore_d     = 8;    // centre bore diameter
eps        = 0.5;  // cut overlap

total_h = 2 * flange_t + core_len;  // 36 mm

difference() {
    union() {
        // bottom flange z = 0..3
        cylinder(d = flange_d, h = flange_t);
        // core z = 3..33 (slight overlap into flanges for a clean union)
        translate([0, 0, flange_t - 0.01])
            cylinder(d = core_d, h = core_len + 0.02);
        // top flange z = 33..36
        translate([0, 0, flange_t + core_len])
            cylinder(d = flange_d, h = flange_t);
    }
    // centre bore through the full height
    translate([0, 0, -eps])
        cylinder(d = bore_d, h = total_h + 2 * eps);
}
